import java.util.*;class Solution{public void wallsAndGates(int[][]r){if(r.length==0)return;Queue<int[]>q=new ArrayDeque<>();for(int i=0;i<r.length;i++)for(int j=0;j<r[0].length;j++)if(r[i][j]==0)q.add(new int[]{i,j});int[][]d={{1,0},{-1,0},{0,1},{0,-1}};while(!q.isEmpty()){int[]p=q.remove();for(int[]z:d){int a=p[0]+z[0],b=p[1]+z[1];if(a>=0&&b>=0&&a<r.length&&b<r[0].length&&r[a][b]==Integer.MAX_VALUE){r[a][b]=r[p[0]][p[1]]+1;q.add(new int[]{a,b});}}}}}
